def W(w,pos,ipa,zh,ja,ex,exz,exj,parts,nz,nj,f1,f2,hl=None,tip=None):
    d=dict(w=w,pos=pos,ipa=ipa,zh=zh,ja=ja,ex=ex,ex_zh=exz,ex_ja=exj,parts=[list(p) for p in parts],note=dict(zh=nz,ja=nj),forms=[list(f1),list(f2)])
    if hl: d['hl']=hl
    if tip: d['tip']=dict(zh=tip[0],ja=tip[1])
    return d
