roots=[R('-prob- / -prov-','Latin probare','检验；证明','試す；証明する','来自拉丁语 probare（检验、证明）。认可 → approve；很可能（经得起检验）→ probable；证明 → prove / proven；探查 → probe。⚠️ improve 来自古法语（获利），并非此词根。','ラテン語 probare（試す・証明する）から。認める → approve；ありそう → probable；証明する → prove / proven；探る → probe。improve は古フランス語（利益を得る）由来で、この語根ではない。',[w['w'] for w in prob]),
R('-test-','Latin testis / testari','见证；证人','証人；証言する','来自拉丁语 testis（证人）和 testari（作证）。为…作证 → attest；共同作证争辩 → contest；公开作证反对 → protest；留下的证明 → testament。⚠️ test 在 testament 里也有“遗嘱”义，别和 text（文本）混淆。','ラテン語 testis（証人）と testari（証言する）から。証明する → attest；争う → contest；公に抗議する → protest；証し → testament。',[w['w'] for w in test]),
R('-qual-','Latin qualis','什么样的；性质','どのような；性質','来自拉丁语 qualis（什么样的）。使具备性质 → qualify；资格 → qualification；去掉资格 → disqualify；性质上的 → qualitative。','ラテン語 qualis（どのような）から。資格を与える → qualify；資格 → qualification；失格 → disqualify；質的な → qualitative。',[w['w'] for w in qual]),
R('-merc- / -mark-','Latin merx / mercari','商品；买卖','商品；売買','来自拉丁语 merx（商品）和 mercari（做买卖）。互相买卖 → commerce；做买卖的人 → merchant；买卖之地 → market。⚠️ mercy（慈悲）与此无关，别混淆。','ラテン語 merx（商品）と mercari（取引する）から。売買し合う → commerce；商人 → merchant；取引の場 → market。mercy（慈悲）は無関係。',[w['w'] for w in merc])]
